/**
 * Built-in polar library.
 *
 * IMPORTANT, and worth repeating in the UI: **none of these are measured polars.**
 * Every entry below is generated by `generatePolar` from the class's published
 * dimensions (LOA, LWL, displacement, working sail area) using the parametric model in
 * docs/02-data-sources/polars.md §2.5. They are plausible, not accurate. Their job is to
 * let someone route their first leg before they have ever heard the word "polar", and to
 * act as the prior that real data — a class polar, an ORC certificate, or a fit to the
 * sailor's own tracks — overwrites.
 *
 * Nothing here is copied from Expedition, qtVlm, OpenCPN, ORC or any other polar set.
 * Dimensions are public class-association / manufacturer specification figures; the
 * numbers in the tables are ours.
 *
 * Displacement figures for dinghies and catamarans include a nominal crew weight,
 * because sail-area/displacement ratio is meaningless for a 59 kg hull sailed by an
 * 80 kg human. Sail area is working sail (main + jib/genoa); the shape templates already
 * account for spinnakers downwind.
 */

import { generatePolar } from '../lib/polar'
import type { BoatDims, BoatType } from '../lib/polar'
import type { PolarTable } from '../lib/types'

export interface PolarLibraryEntry {
  id: string
  name: string
  type: BoatType
  loaM: number
  polar: PolarTable
}

interface LibrarySpec {
  id: string
  name: string
  dims: BoatDims
  /** Where the dimensions came from, and anything worth knowing about the fit. */
  note: string
}

