/**
 * The library, built once at module load.
 *
 * Generation is a few hundred float operations per boat, so doing it eagerly costs less
 * than the bytes a hand-written table would have taken in the bundle.
 */
export const POLAR_LIBRARY: PolarLibraryEntry[] = SPECS.map((s) => {
  const polar = generatePolar(s.dims, s.name)
  polar.source = `${s.note} Parametric model: docs/02-data-sources/polars.md §2.5.`
  return { id: s.id, name: s.name, type: s.dims.type, loaM: s.dims.loaM, polar }
})

const BY_ID = new Map(POLAR_LIBRARY.map((e) => [e.id, e]))

/** Look up a built-in polar by its stable id. Ids are persisted in boat setup. */
export function findPolar(id: string): PolarLibraryEntry | undefined {
  return BY_ID.get(id)
}
